// User Level Code (x86_64 Linux)
// Requesting Privileged H/W Access (I/O)

// Syscall convention (ECF Entry Point):
// RAX: Syscall ID (0=read, 1=write)
// RDI, RSI, RDX: Args 1-3

const long SYS_WRITE = 1;
char buffer[] = "data";
long bytes_written;

__asm__ volatile (
    "mov %3, %%rax\n"  // Set SYS_WRITE (ID)
    "mov $1, %%rdi\n"  // Arg 1: FD=1 (STDOUT)
    "mov %1, %%rsi\n"  // Arg 2: Buffer Address
    "mov %2, %%rdx\n"  // Arg 3: Length
    "syscall\n"        // ECF Trigger: User -> Kernel (Privileged Mode)
    : "=a" (bytes_written)
    : "g" (buffer), "g" (sizeof(buffer)), "i" (SYS_WRITE)
    : "rdi", "rsi", "rdx", "rcx", "r11"
);
// ECF Exit: Kernel returns to user mode, result in RAX (bytes_written)
